	public virtual void DecorateTupleList(List<Tuple<TileGridSection, Room>> givenList)
	{
		int count = givenList.Count;
		for (int i = 0; i < count; i++)
		{
			if (givenList[i].Second.randomEnemies || givenList[i].Second.type == RoomType.FloorPlan)
			{
				Decorate(givenList[i].First, givenList[i].Second);
			}
		}
	}

