	public BlobDeadState(string newName, FSM newFSM, Blob newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		blobMiniPrefab = ChaosBundle.Get("Assets/Prefabs/Enemies/BlobMini.prefab");
		blobPrefab = ChaosBundle.Get("Assets/Prefabs/Enemies/Blob.prefab");
	}

	public override void OnEnter()
	{
		PoolManager.GetPoolItem<ParticleEffect>("BlobEffect").Emit(6, parent.transform.position);
		parent.auraEmitter.enableEmission = false;
		parent.auraEmitter.Clear();
		if (parent.fsm.previousStateName.Contains("Fall"))
		{
			parent.divide = false;
			parent.dropLoot = true;
		}
		base.OnEnter();
		if (parent.divide)
		{
			parent.movement.EndMovement();
			blobSpawnCount = ((GameController.CurrentDifficulty <= 1) ? 2 : 3);
			for (int i = 0; i < blobSpawnCount; i++)
			{
				throwVector = UnityEngine.Random.Range(0.5f, 1.35f) * Globals.GetCirclePositionVector(blobSpawnCount, i);
				SpawnBlob(parent.transform.position, spawnAsThrown: true, throwVector);
			}
		}
	}

	public virtual Blob SpawnBlob(Vector2 spawnLocation, bool spawnAsThrown = false, Vector2? unNormalizedThrowVector = null, float range = 10f)
	{
		if (unNormalizedThrowVector.HasValue && !divideMini)
		{
			spawnLocation += unNormalizedThrowVector.Value.normalized;
		}
		Vector2 origin = spawnLocation;
		bool randomize = !divideMini;
		Vector2 availableNearbyLocation = Entity.GetAvailableNearbyLocation(origin, excludeOrigin: false, randomize);
		spawnLocation = ((!(availableNearbyLocation == Vector2.zero)) ? availableNearbyLocation : ((Vector2)parent.transform.position));
		Blob component = UnityEngine.Object.Instantiate((!divideMini) ? blobPrefab : blobMiniPrefab, spawnLocation, Quaternion.identity).GetComponent<Blob>();
		if (!divideMini)
		{
			component.transform.SetParent(parent.transform.parent);
		}
		if (parent.parentFactoryList != null)
		{
			parent.parentFactoryList.Add(component);
			component.parentFactoryList = parent.parentFactoryList;
		}
		PoolManager.GetPoolItem<ParticleEffect>("BlobEffect").Emit(4, parent.transform.position);
		component.divide = false;
		component.countDeathInStats = false;
		component.dropLoot = parent.childrenDropLoot;
		component.childrenDropLoot = parent.childrenDropLoot;
		component.transform.SetParent(parent.transform.parent);
		component.attackRadius = parent.attackRadius;
		component.escapeRadius = parent.escapeRadius;
		component.alertRadius = parent.alertRadius;
		component.canAlertOthers = false;
		component.health.SetInvulnerabilityDuration(0.25f, showMsg: false);
		if (parent != null && parent.health != null && parent.health.lastAttack != null)
		{
			component.health.lastAttack = null;
			component.fsm.ChangeState("Hurt");
		}
		if (spawnAsThrown && unNormalizedThrowVector.HasValue)
		{
			ThrownItem thrownItem = component.gameObject.AddComponent<ThrownItem>();
			thrownItem.targetPosition = (Vector2)parent.transform.position + unNormalizedThrowVector.Value;
			thrownItem.spriteTrans = component.spriteTrans;
			thrownItem.useCalculatedValues = false;
			thrownItem.updateFloorContact = true;
			thrownItem.useLineCastPosition = true;
			if (divideMini)
			{
				thrownItem.throwHeight = UnityEngine.Random.Range(1f, 1.25f);
			}
			else
			{
				thrownItem.throwHeight = UnityEngine.Random.Range(1.5f, 2.75f);
			}
		}
		return component;
	}
